function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof WADIYAR_INFO&&(n.innerHTML=WADIYAR_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderEducation(){const n=document.getElementById("education-grid");n&&"undefined"!=typeof EDUCATION_INSTITUTIONS&&(n.innerHTML=EDUCATION_INSTITUTIONS.map(n=>`\n        <div class="edu-card">\n            <span class="category-tag">${n.category}</span>\n            <h3>🎓 ${n.name}</h3>\n            <p><strong>Established:</strong> ${n.establishedYear}</p>\n            <p>${n.contribution}</p>\n        </div>\n    `).join(""))}function renderInfrastructure(){const n=document.getElementById("infra-grid");n&&"undefined"!=typeof INFRASTRUCTURE_PROJECTS&&(n.innerHTML=INFRASTRUCTURE_PROJECTS.map(n=>`\n        <div class="infra-card">\n            <span class="infra-icon">${n.icon}</span>\n            <h3>${n.title}</h3>\n            <p>${n.impact}</p>\n        </div>\n    `).join(""))}function renderCulture(){const n=document.getElementById("culture-grid");n&&"undefined"!=typeof CULTURAL_HERITAGE&&(n.innerHTML=CULTURAL_HERITAGE.map(n=>`\n        <div class="culture-card">\n            <h3>🏰 ${n.title}</h3>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderEducation(),renderInfrastructure(),renderCulture(),renderTimeline(),renderReferences(),initThemeToggle()});